code_snippets.parse_list:
def parse(self, response):
    for li in response.css('ul li'):
        detail_links = li.css('#site-navigation a::attr(href)').getall()
        for link in detail_links:
            yield response.follow(link, self.parse_detail)

code_snippets.parse_detail:
def parse_detail(self, response):
    title = response.css('head > title::text').get()
    pdf_urls = response.css('a[href$=".pdf"]::attr(href)').getall()
    for pdf_url in pdf_urls:
        yield {'title': title, 'pdf_url': response.urljoin(pdf_url)}
